-- Katalog seed — catalog_data JSON'larından scripts/seed-catalog.ts ile üretildi.
-- Yeniden üretmek için: npx tsx scripts/seed-catalog.ts --kinds rope --brands İzmit A.Ş. --replace --out 20260903000002_izmit_rope_reseed
-- Toplam 1861 ürün.

-- Bu markanın katalog satırları kaynak JSON'dan yeniden üretilir.
delete from public.cat_equipment where brand in ('İzmit A.Ş.') and kind in ('rope');





on conflict (key) do update set value = excluded.value, updated_at = now();
